		insert into CHB_INVESTHOLD_INFO_SUB 
		(
		REGIST_SEQNO,REGIST_BANK_CODE,CHB_SUBMIT_DEADLINE,PRD_REGIST_CODE,INDENTIFY_MARK,CCY,
		HOLD_DATE,AMOUNT,QTY,CNY_AMT,REMARK,SUBMIT_DEADLINE,WORKFLOW_ID,SEND_STATUS,
		STATUS_DATE,STATUS,CREATE_USER,CREATE_TIME,UPDATE_USER,UPDATE_TIME,
		ORG_CODE,DEPT_CODE,SUBMIT_TIME,PRODID
            )
        select A.* from (

            select  #{item.registSeqno,jdbcType=VARCHAR},REGIST_BANK_CODE,#{item.chbSubmitDeadline,jdbcType=TIMESTAMP},
            	PRD_REGIST_CODE,INDENTIFY_MARK,CCY,HOLD_DATE,AMOUNT,QTY,CNY_AMT,REMARK,
            	#{item.submitDeadline,jdbcType=TIMESTAMP},WORKFLOW_ID,'01',#{item.statusDate,jdbcType=TIMESTAMP},
            	#{item.status,jdbcType=VARCHAR},CREATE_USER,CREATE_TIME,UPDATE_USER,UPDATE_TIME,ORG_CODE,DEPT_CODE,null,PRODID     
        	from chb_investhold_info
         	where INDENTIFY_MARK = #{item.indentifyMark} and REGIST_BANK_CODE = #{item.registBankCode}
         	    and PRD_REGIST_CODE= #{item.prdRegistCode,jdbcType=VARCHAR}
				and CCY= #{item.ccy,jdbcType=VARCHAR}
				and HOLD_DATE= #{item.holdDate,jdbcType=DATE}

         )A

